/**
 * Tier-2 date and date/time builders for the calc DSL.
 *
 * The platform's calc grammar treats DATE and DATETIME as distinct
 * brands — DATE is calendar date (no time component), DATETIME is
 * instant-in-time. Knowhere accepts either brand for date-part extraction
 * and DATETIME_TRUNC.
 *
 * Constrained string arguments are typed as literal unions so the
 * agent gets autocomplete and compile-time validation:
 *   - `dateDif` unit: 'S' | 'MIN' | 'H' | 'Y' | 'M' | 'D'
 *   - `dateTimeTrunc` precision: a date-part literal union
 *   - `weekday` mode: 1 | 2 | 3
 */
import type { ComposedExpr, Expr, ExprLike } from "./types.js";
/** Either a DATE-typed or DATETIME-typed expression. */
type DateOrDateTimeLike = ExprLike<"date"> | ExprLike<"datetime">;
/** Current instant. Wire `NOW()`. Returns DATETIME. */
export declare function now(): Expr<"datetime">;
/**
 * Build a DATE from numeric year / month / day components.
 * Wire `DATE(year, month, day)`. The `make` prefix avoids colliding
 * with the JS `Date` global if someone destructures `calc`.
 */
export declare function makeDate<const Year extends ExprLike<"number">, const Month extends ExprLike<"number">, const Day extends ExprLike<"number">>(year: Year, month: Month, day: Day): ComposedExpr<"date", [Year, Month, Day]>;
/**
 * Build a DATETIME from numeric date and time components.
 * Wire `DATETIME(year, month, day, hour, minute, second)`.
 */
export declare function dateTime<const Parts extends readonly [ExprLike<"number">, ExprLike<"number">, ExprLike<"number">, ExprLike<"number">, ExprLike<"number">, ExprLike<"number">]>(...values: Parts): ComposedExpr<"datetime", Parts>;
/**
 * Parse a text expression into a DATE. The server accepts ISO-style
 * `YYYY-MM-DD` literals; with a text expression as input the server
 * does a TRY_CAST and returns null on parse failure.
 */
export declare function dateValue<const Value extends ExprLike<"text"> | ExprLike<"datetime">>(value: Value): ComposedExpr<"date", [Value]>;
/** Discoverable unit codes accepted by the wire `DATEDIF` function. */
export declare const dateDifUnit: {
    readonly seconds: "S";
    readonly minutes: "MIN";
    readonly hours: "H";
    readonly years: "Y";
    readonly months: "M";
    readonly days: "D";
};
export type DateDifUnit = (typeof dateDifUnit)[keyof typeof dateDifUnit];
/** Human-readable date difference units accepted by {@link dateDiff}. */
export declare const dateDiffUnit: {
    readonly seconds: "seconds";
    readonly minutes: "minutes";
    readonly hours: "hours";
    readonly years: "years";
    readonly months: "months";
    readonly days: "days";
};
export type DateDiffUnit = keyof typeof dateDiffUnit;
/**
 * Difference between `end` and `start` in the specified unit.
 * - `'S'` — seconds; `'MIN'` — minutes; `'H'` — hours
 * - `'D'` — days; `'M'` — months; `'Y'` — years
 */
/** @deprecated Prefer {@link dateDiff} with human-readable units. */
export declare function dateDif<const Start extends DateOrDateTimeLike, const End extends DateOrDateTimeLike>(start: Start, end: End, unit: DateDifUnit): ComposedExpr<"number", [Start, End]>;
/** Difference between two dates using a readable unit name. */
export declare function dateDiff<const Start extends DateOrDateTimeLike, const End extends DateOrDateTimeLike>(start: Start, end: End, unit: DateDiffUnit): ComposedExpr<"number", [Start, End]>;
/** Discoverable precision values accepted by `DATETIME_TRUNC`. */
export declare const dateTimeTruncPrecision: {
    readonly microseconds: "MICROSECONDS";
    readonly milliseconds: "MILLISECONDS";
    readonly second: "SECOND";
    readonly minute: "MINUTE";
    readonly hour: "HOUR";
    readonly day: "DAY";
    readonly week: "WEEK";
    readonly month: "MONTH";
    readonly quarter: "QUARTER";
    readonly year: "YEAR";
    readonly decade: "DECADE";
    readonly century: "CENTURY";
    readonly millennium: "MILLENNIUM";
};
export type DateTimeTruncPrecision = (typeof dateTimeTruncPrecision)[keyof typeof dateTimeTruncPrecision];
/** Human-readable precisions accepted by {@link truncateDateTime}. */
export type DateTimePrecision = "microseconds" | "milliseconds" | "second" | "minute" | "hour" | "day" | "week" | "month" | "quarter" | "year" | "decade" | "century" | "millennium";
/**
 * Truncate a DATE or DATETIME to the given precision. E.g.
 * `dateTimeTrunc(t, "MONTH")` returns the first instant of `t`'s month.
 */
/** @deprecated Prefer {@link truncateDateTime} with human-readable precision. */
export declare function dateTimeTrunc<const Value extends DateOrDateTimeLike>(value: Value, precision: DateTimeTruncPrecision): ComposedExpr<"datetime", [Value]>;
/** Truncate a date/datetime using a readable precision name. */
export declare function truncateDateTime<const Value extends DateOrDateTimeLike>(value: Value, precision: DateTimePrecision): ComposedExpr<"datetime", [Value]>;
/**
 * Modes accepted by the wire `WEEKDAY` function.
 *   - 1 — Sunday=1 .. Saturday=7  (default)
 *   - 2 — Monday=1 .. Sunday=7
 *   - 3 — Monday=0 .. Sunday=6
 */
export declare const weekdayMode: {
    readonly sundayOne: 1;
    readonly mondayOne: 2;
    readonly mondayZero: 3;
};
export type WeekdayMode = (typeof weekdayMode)[keyof typeof weekdayMode];
export type WeekdayConvention = keyof typeof weekdayMode;
/**
 * Day-of-week as a numeric, optionally selecting the numbering scheme.
 */
export declare function weekday<const Value extends DateOrDateTimeLike>(value: Value, mode?: WeekdayMode | WeekdayConvention): ComposedExpr<"number", [Value]>;
/** Year component as NUMBER. */
export declare function year<const Value extends DateOrDateTimeLike>(value: Value): ComposedExpr<"number", [Value]>;
/** Month component (1–12) as NUMBER. */
export declare function month<const Value extends DateOrDateTimeLike>(value: Value): ComposedExpr<"number", [Value]>;
/** Day-of-month (1–31) as NUMBER. */
export declare function day<const Value extends DateOrDateTimeLike>(value: Value): ComposedExpr<"number", [Value]>;
/** Hour (0–23) from a DATE or DATETIME. */
export declare function hour<const Value extends DateOrDateTimeLike>(value: Value): ComposedExpr<"number", [Value]>;
/** Minute (0–59) from a DATE or DATETIME. */
export declare function minute<const Value extends DateOrDateTimeLike>(value: Value): ComposedExpr<"number", [Value]>;
/** Second (0–59) from a DATE or DATETIME. */
export declare function second<const Value extends DateOrDateTimeLike>(value: Value): ComposedExpr<"number", [Value]>;
export {};
